from fastapi import FastAPI
from fastapi.testclient import TestClient

app = FastAPI()


@app.get("/limited", rate_limit="50/minute")
def limited():
    return {"ok": True}


@app.get("/unlimited")
def unlimited():
    return {"ok": True}


client = TestClient(app)


def test_openapi_includes_x_rate_limit_when_set():
    response = client.get("/openapi.json")
    assert response.status_code == 200, response.text
    paths = response.json()["paths"]
    assert paths["/limited"]["get"]["x-rate-limit"] == "50/minute"


def test_openapi_omits_x_rate_limit_when_not_set():
    response = client.get("/openapi.json")
    assert response.status_code == 200, response.text
    paths = response.json()["paths"]
    assert "x-rate-limit" not in paths["/unlimited"]["get"]

