from fastapi import FastAPI, APIRouter

# nested routers
inner = APIRouter()
@inner.get("/inner-limited", rate_limit="5/minute")
def inner_limited():
    return {"ok": True}

middle = APIRouter()
middle.include_router(inner, prefix="/inner")
@middle.get("/middle-limited", rate_limit="10/minute")
def middle_limited():
    return {"ok": True}

app = FastAPI()
app.include_router(middle, prefix="/middle")

from fastapi.testclient import TestClient
client = TestClient(app)
r = client.get("/openapi.json")
paths = r.json()["paths"]
for p, methods in paths.items():
    for m, op in methods.items():
        print(f"  {p} {m} x-rate-limit: {op.get('x-rate-limit')}")
